import { Octokit } from "@octokit/rest";
import { independentApprovers, requesters } from "./independent-approval-rules.js";

const token = process.env.GITHUB_TOKEN;
if (!token) throw new Error("GITHUB_TOKEN is not set");
const [owner, repo] = process.env.GITHUB_REPOSITORY!.split("/");
const pull_number = Number(process.env.PR_NUMBER);

const octokit = new Octokit({ auth: token });

const { data: pr } = await octokit.rest.pulls.get({ owner, repo, pull_number });
const headSha = pr.head.sha;
console.log(`PR #${pull_number} by ${pr.user.login}, head ${headSha.slice(0, 7)}`);

const reviews = await octokit.paginate(octokit.rest.pulls.listReviews, { owner, repo, pull_number, per_page: 100 });
const commits = await octokit.paginate(octokit.rest.pulls.listCommits, { owner, repo, pull_number, per_page: 100 });

const commitAuthors = commits.map((c) => c.author?.login).filter((l): l is string => !!l);
const bodyEditors: string[] = []; // body edit history needs the GraphQL userContentEdits field; see the GraphQL section

const people = requesters({ user: { login: pr.user.login }, body: pr.body }, commitAuthors, bodyEditors);
const approvers = independentApprovers(
  reviews.map((r) => ({ state: r.state, commit_id: r.commit_id, user: { login: r.user!.login, type: r.user!.type } })),
  headSha,
  people,
);

if (approvers.size === 0) {
  console.log(`no independent approval on ${headSha.slice(0, 7)}; requesters: ${[...people].join(", ")}`);
  process.exitCode = 1;
} else {
  console.log(`approved by ${[...approvers].join(", ")}`);
}

export const checkRunsFor = async (owner: string, repo: string, sha: string) => {
  const runs = await octokit.paginate(octokit.rest.checks.listForRef, { owner, repo, ref: sha, per_page: 100 });
  return runs.map((c) => ({
    name: c.name,
    head_sha: c.head_sha,
    conclusion: c.conclusion, // "success" | "failure" | "skipped" | ... | null while running
    started_at: c.started_at ?? "",
  }));
};

// workflow runs of one file on main, for red-main hours (G1-06)
const { data } = await octokit.rest.actions.listWorkflowRuns({
  owner, repo, workflow_id: "cloud-ci.yml", branch: "main", status: "completed", per_page: 100,
});
const { data: jobs } = await octokit.rest.actions.listJobsForWorkflowRun({ owner, repo, run_id: data.workflow_runs[0].id });

export const openDraftPr = async (branch: string, title: string, body: string, requester: string) => {
  const { data: pr } = await octokit.rest.pulls.create({
    owner, repo,
    base: "main",
    head: branch,
    title,
    body: `${body}\n\nRequested-by: @${requester}`,
    draft: true,
  });
  await octokit.rest.issues.addLabels({ owner, repo, issue_number: pr.number, labels: ["ai-agent"] })
    .catch((e) => console.warn(`label failed: ${e.message}`));
  await octokit.rest.pulls.requestReviewers({ owner, repo, pull_number: pr.number, team_reviewers: ["frontend-guild"] })
    .catch((e) => console.warn(`reviewers failed: ${e.message}`));
  return pr.html_url;
};

const QUERY = `
query($q: String!, $after: String) {
  search(query: $q, type: ISSUE, first: 50, after: $after) {
    pageInfo { hasNextPage endCursor }
    nodes { ... on PullRequest {
      number createdAt mergedAt bodyText author { login }
      commits(first: 100) { nodes { commit { authoredDate message } } }
      timelineItems(itemTypes: [READY_FOR_REVIEW_EVENT, PULL_REQUEST_REVIEW], first: 50) {
        nodes { __typename
          ... on ReadyForReviewEvent { createdAt }
          ... on PullRequestReview { createdAt state author { login __typename } } } }
    } }
  }
}`;
// called as graphql(QUERY, { q: `repo:${repo} is:pr created:${weekStart}..${weekEnd}`, after })
